    subjectName: '給排水衛生設備',
    category: '排水・通気設備',
    question: '通気設備に関する記述のうち、最も不適当なものはどれか。',
    choices: [
      { key: 'A', text: '通気管は、排水管内の圧力変動とは無関係であり、専ら建物の換気（室内空気の入れ替え）を目的として設けられる設備である。', explanation: '不適当。通気管は排水系統内の圧力変動を緩和しトラップの封水を保護すること等を主目的とする設備であり、室内の換気（空気の入れ替え）を目的とする設備ではない。目的を混同した記述である。' },
      { key: 'B', text: '伸頂通気方式は、最上部の排水立て管をそのまま延長して大気に開放する通気方式である。', explanation: '適当。排水立て管の頂部を延長し大気開放することで、簡易な通気を確保する方式である。' },
      { key: 'C', text: 'ループ通気方式は、複数の器具排水管を一括して通気立て管に接続する通気方式で、多くの器具がある場合に用いられる。', explanation: '適当。最上流の器具排水管からループ状に通気管を立ち上げ通気立て管に接続する方式で、比較的多数の器具に対応できる。' },
      { key: 'D', text: '通気管の末端（大気開放部）は、窓・換気口等の開口部から一定の距離を確保して設置することが望ましいとされる。', explanation: '適当。臭気の室内への侵入を防ぐため、通気管末端は窓等の開口部からある程度離して設置することが求められる。' },
    ],
