    question: '受水槽・高置水槽の構造に関する記述のうち、最も不適当なものはどれか。',
    choices: [
      { key: 'A', text: '受水槽は、点検・清掃の必要がないよう、床・壁に密着させて設置することが望ましいとされる。', explanation: '不適当。受水槽は内部の点検・清掃のため、床・壁・天井から一定の離隔距離を確保し、六面点検が可能な状態で設置することが求められており、「床・壁に密着させることが望ましい」というのは衛生管理上誤りである。' },
      { key: 'B', text: '受水槽には、槽内の水が長期間滞留しないよう、流入管と流出管の位置を離す等、水の滞留（デッドスペース）を防ぐ工夫が求められる。', explanation: '適当。流入・流出位置が近いと水が滞留しやすく水質悪化の原因となるため、対角配置等の工夫が求められる。' },
      { key: 'C', text: '受水槽のオーバーフロー管には、虫等の侵入を防止する防虫網を設けるとともに、排水管に直接接続しない（間接排水とする）ことが求められる。', explanation: '適当。オーバーフロー管を排水管に直結すると排水の逆流のおそれがあるため、間接排水とすることが求められる。' },
      { key: 'D', text: '受水槽の周囲には、他の配管等と兼用させず、飲料水専用であることが判別できるよう配慮することが求められる。', explanation: '適当。誤接続や汚染防止のため、受水槽・配管が飲料水専用であることを明示・区別することが求められる。' },
    ],
