    choices: [
      { key: 'A', text: '閉鎖型スプリンクラーヘッドは、感熱部が一定温度に達すると開放し散水する、事務所・ホテル等で広く用いられるヘッドである。', explanation: '適当。通常時は閉じており火災の熱で感熱部が作動して開放する方式で、一般建築物に広く採用される。' },
      { key: 'B', text: '開放型スプリンクラーヘッドは、常時開放されており、一斉開放弁の作動により系統全体で一斉に散水する方式で、舞台部等に用いられる。', explanation: '適当。劇場の舞台部等、火災の急速な拡大が懸念される部位では、ヘッド自体は常時開放とし、感知器・一斉開放弁で系統一括放水する方式が用いられる。' },
      { key: 'C', text: '閉鎖型スプリンクラーヘッドは、常時開放された状態にあり、火災の有無にかかわらず一斉開放弁の作動により放水する方式である。', explanation: '不適当。常時開放され一斉開放弁の作動により系統一括で放水するのは「開放型」スプリンクラーヘッドの方式であり、「閉鎖型」は通常時閉じていて感熱部が火災の熱で作動し個別に開放する方式である。両者の説明が入れ替わっている。' },
      { key: 'D', text: '屋外消火栓設備は、建築物の外部からの消火活動や、延焼防止を目的として敷地内に設置される消火設備である。', explanation: '適当。屋外に設置され、建物外部からの初期消火・延焼防止活動に用いられる設備である。' },
    ],
    correctKey: 'C',
    explanation: '閉鎖型は個別感熱作動、開放型は一斉開放弁で系統一括放水。屋外消火栓は建物外部からの活動用。\n【図解】\n　スプリンクラー・消火設備の要点\n　閉鎖型ヘッド：個別に感熱作動★（一般建築物向き）\n　開放型ヘッド：一斉開放弁で系統一括放水★（舞台部等）\n　屋外消火栓：建物外部からの消火・延焼防止★\n　不活性ガス消火：水を使わず酸欠状態で消火★',
