    question: '給水設備の水質管理に関する記述のうち、最も不適当なものはどれか。',
    choices: [
      { key: 'A', text: '受水槽・高置水槽等の貯水槽は、一度設置すれば水質が劣化することはなく、定期的な清掃は不要とされている。', explanation: '不適当。貯水槽は槽内への汚れの堆積や生物膜の形成等により水質が劣化するおそれがあるため、定期的な清掃（年1回程度を目安とする等）による衛生管理が求められており、「清掃は不要」というのは誤りである。' },
      { key: 'B', text: '給水系統の残留塩素濃度は、水道水の消毒効果を維持するための指標の一つとして、定期的な検査が行われることがある。', explanation: '適当。末端給水栓での残留塩素の確認は、貯水槽水道等における衛生管理上の代表的な検査項目である。' },
      { key: 'C', text: '貯水槽の水は長期間滞留すると水質が劣化しやすいため、水の使用量に応じた適切な容量設定や水の入れ替わりへの配慮が必要である。', explanation: '適当。過大な貯水槽容量は水の滞留時間を長くし水質悪化を招きやすいため、使用実態に応じた容量計画が求められる。' },
      { key: 'D', text: '給水管の材質には、耐食性・衛生性に配慮した管種（ステンレス鋼管、樹脂管等）が用いられることが多い。', explanation: '適当。腐食による赤水の発生や衛生性の低下を防ぐため、耐食性に優れた管材が採用されることが多い。' },
    ],
